1	// Package service implements the WorkspaceService that orchestrates read queries
2	// and RPC calls to adapter-service.
3	package service
4	
5	import (
6		"context"
7		"encoding/json"
8		"errors"
9		"time"
10	
11		"github.com/tiendv89/workflow-backend/internal/adapter"
12		"github.com/tiendv89/workflow-backend/internal/database"
13		"github.com/tiendv89/workflow-backend/internal/domain"
14	)
15	
16	// DatabaseReader is the read-only interface over the shared PostgreSQL schema.
17	type DatabaseReader interface {
18		ListWorkspaces(ctx context.Context) ([]database.Workspace, error)
19		GetWorkspace(ctx context.Context, workspaceID string) (database.Workspace, error)
20		GetGitHubSource(ctx context.Context, workspaceID string) (database.WorkspaceGitHubSource, error)
21		ListGitHubSources(ctx context.Context) ([]database.WorkspaceGitHubSource, error)
22		ListLatestSyncRunsPerWorkspace(ctx context.Context) ([]database.WorkspaceSyncRun, error)
23		GetLatestSyncRun(ctx context.Context, workspaceID string) (database.WorkspaceSyncRun, error)
24		ListWorkspaceFeatures(ctx context.Context, workspaceID string) ([]database.WorkspaceFeature, error)
25		SearchWorkspaceFeatures(ctx context.Context, workspaceID string, filters database.FeatureSearchFilters) ([]database.WorkspaceFeature, error)
26		CountWorkspaceFeatures(ctx context.Context, workspaceID string, filters database.FeatureSearchFilters) (int, error)
27		ListFeatureTaskCounts(ctx context.Context, workspaceID string, featureIDs []string) ([]database.WorkspaceFeatureTaskCounts, error)
28		GetWorkspaceFeature(ctx context.Context, workspaceID, featureID string) (database.WorkspaceFeature, error)
29		ListFeatureDocuments(ctx context.Context, workspaceID, featureID string) ([]database.WorkspaceFeatureDocument, error)
30		ListFeatureTasks(ctx context.Context, workspaceID, featureID string) ([]database.WorkspaceTask, error)
31		SearchFeatureTasks(ctx context.Context, workspaceID, featureID string, filters database.TaskSearchFilters) ([]database.WorkspaceTask, error)
32		CountFeatureTasks(ctx context.Context, workspaceID, featureID string, filters database.TaskSearchFilters) (int, error)
33		SearchWorkspaceTasks(ctx context.Context, workspaceID string, filters database.TaskSearchFilters) ([]database.WorkspaceTask, error)
34		CountWorkspaceTasks(ctx context.Context, workspaceID string, filters database.TaskSearchFilters) (int, error)
35		ListWorkspaceTasks(ctx context.Context, workspaceID string) ([]database.WorkspaceTask, error)
36		GetWorkspaceTask(ctx context.Context, workspaceID, featureID, taskID string) (database.WorkspaceTask, error)
37		GetWorkspaceTaskByID(ctx context.Context, workspaceID, taskID string) (database.WorkspaceTask, error)
38		ListActivityEvents(ctx context.Context, workspaceID, featureID, taskID string) ([]database.WorkspaceActivityEvent, error)
39	}
40	
41	// AdapterCaller issues RPC calls to adapter-service for write operations.
42	type AdapterCaller interface {
43		ImportWorkspace(ctx context.Context, req adapter.ImportRequest) (string, error)
44		SyncWorkspace(ctx context.Context, workspaceID string) error
45	}
46	
47	// WorkspaceService orchestrates reads from PostgreSQL and calls to adapter-service.
48	type WorkspaceService struct {
49		db             DatabaseReader
50		adapter        AdapterCaller
51		staleThreshold time.Duration
52	}
53	
54	// New creates a new WorkspaceService.
55	func New(db DatabaseReader, adapterClient AdapterCaller, staleThreshold time.Duration) *WorkspaceService {
56		return &WorkspaceService{
57			db:             db,
58			adapter:        adapterClient,
59			staleThreshold: staleThreshold,
60		}
61	}
62	
63	// ListWorkspaces returns summary rows for all saved workspaces with source state.
64	func (s *WorkspaceService) ListWorkspaces(ctx context.Context) ([]domain.WorkspaceSummary, error) {
65		rows, err := s.db.ListWorkspaces(ctx)
66		if err != nil {
67			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
68		}
69	
70		// Batch-load latest sync run per workspace to avoid N+1 queries.
71		allRuns, err := s.db.ListLatestSyncRunsPerWorkspace(ctx)
72		if err != nil {
73			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
74		}
75		runMap := make(map[string]database.WorkspaceSyncRun, len(allRuns))
76		for _, run := range allRuns {
77			runMap[database.UUIDString(run.WorkspaceID)] = run
78		}
79	
80		// Batch-load GitHub sources to avoid N+1 queries.
81		allSrcs, err := s.db.ListGitHubSources(ctx)
82		if err != nil {
83			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
84		}
85		srcMap := make(map[string]string, len(allSrcs))
86		for _, src := range allSrcs {
87			srcMap[database.UUIDString(src.WorkspaceID)] = src.RepoURL
88		}
89	
90		out := make([]domain.WorkspaceSummary, 0, len(rows))
91		for _, r := range rows {
92			wsID := database.UUIDString(r.ID)
93			srcRun, ok := runMap[wsID]
94			var ss domain.SourceState
95			if ok {
96				ss = toSourceState(&srcRun, s.staleThreshold)
97			} else {
98				ss = domain.DeriveSourceState(nil, s.staleThreshold)
99			}
100	
101			repoURL := srcMap[wsID]
102			out = append(out, domain.WorkspaceSummary{
103				ID:          wsID,
104				Name:        r.Name,
105				Slug:        r.Slug,
106				RepoURL:     repoURL,
107				SourceState: ss,
108				UpdatedAt:   r.UpdatedAt.Time,
109			})
110		}
111		return out, nil
112	}
113	
114	// ImportWorkspace calls adapter-service to import/persist a workspace, then
115	// returns the normalized persisted detail from PostgreSQL.
116	func (s *WorkspaceService) ImportWorkspace(ctx context.Context, input domain.ImportInput) (*domain.WorkspaceDetail, domain.SourceError) {
117		workspaceID, err := s.adapter.ImportWorkspace(ctx, adapter.ImportRequest{
118			RepoURL:       input.RepoURL,
119			DefaultBranch: input.DefaultBranch,
120			Name:          input.Name,
121		})
122		if err != nil {
123			if se, ok := err.(domain.SourceError); ok {
124				return nil, se
125			}
126			return nil, domain.NewAdapterError(domain.ErrAdapterInternal, err.Error())
127		}
128	
129		return s.GetWorkspace(ctx, workspaceID)
130	}
131	
132	// GetWorkspaceSummary returns only basic workspace information without loading features/tasks.
133	func (s *WorkspaceService) GetWorkspaceSummary(ctx context.Context, workspaceID string) (*domain.WorkspaceSummary, domain.SourceError) {
134		ws, err := s.db.GetWorkspace(ctx, workspaceID)
135		if err != nil {
136			if errors.Is(err, database.ErrNotFound) {
137				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
138			}
139			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
140		}
141	
142		wsID := database.UUIDString(ws.ID)
143		syncRun, err := s.db.GetLatestSyncRun(ctx, wsID)
144		var ss domain.SourceState
145		if errors.Is(err, database.ErrNotFound) || err != nil {
146			ss = domain.DeriveSourceState(nil, s.staleThreshold)
147		} else {
148			ss = toSourceState(&syncRun, s.staleThreshold)
149		}
150	
151		return &domain.WorkspaceSummary{
152			ID:          wsID,
153			Name:        ws.Name,
154			Slug:        ws.Slug,
155			RepoURL:     s.githubRepoURL(ctx, wsID),
156			SourceState: ss,
157			UpdatedAt:   ws.UpdatedAt.Time,
158		}, domain.SourceError{}
159	}
160	
161	// GetWorkspace returns full workspace detail with features, tasks, and source state.
162	func (s *WorkspaceService) GetWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, domain.SourceError) {
163		ws, err := s.db.GetWorkspace(ctx, workspaceID)
164		if err != nil {
165			if errors.Is(err, database.ErrNotFound) {
166				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
167			}
168			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
169		}
170	
171		wsID := database.UUIDString(ws.ID)
172	
173		features, err := s.db.ListWorkspaceFeatures(ctx, wsID)
174		if err != nil {
175			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
176		}
177	
178		tasks, err := s.db.ListWorkspaceTasks(ctx, wsID)
179		if err != nil {
180			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
181		}
182	
183		taskCountsByFeature := countTasksByFeature(tasks)
184	
185		syncRun, err := s.db.GetLatestSyncRun(ctx, wsID)
186		var ss domain.SourceState
187		if errors.Is(err, database.ErrNotFound) || err != nil {
188			ss = domain.DeriveSourceState(nil, s.staleThreshold)
189		} else {
190			ss = toSourceState(&syncRun, s.staleThreshold)
191		}
192	
193		featureSummaries := make([]domain.FeatureSummary, 0, len(features))
194		for _, f := range features {
195			counts := taskCountsByFeature[database.UUIDString(f.FeatureID)]
196			featureSummaries = append(featureSummaries, domain.FeatureSummary{
197				ID:           database.UUIDString(f.ID),
198				FeatureID:    database.UUIDString(f.FeatureID),
199				FeatureName:  f.FeatureName,
200				Title:        f.Title,
201				Status:       derefStr(f.FeatureStatus),
202				CurrentStage: derefStr(f.CurrentStage),
203				Stages:       rawJSONOrNil(f.Stages),
204				UpdatedAt:    f.UpdatedAt.Time,
205				TaskCounts:   counts,
206			})
207		}
208	
209		taskSummaries := make([]domain.TaskSummary, 0, len(tasks))
210		for _, t := range tasks {
211			taskSummaries = append(taskSummaries, toTaskSummary(t))
212		}
213	
214		repoURL := s.githubRepoURL(ctx, wsID)
215		return &domain.WorkspaceDetail{
216			WorkspaceSummary: domain.WorkspaceSummary{
217				ID:          wsID,
218				Name:        ws.Name,
219				Slug:        ws.Slug,
220				RepoURL:     repoURL,
221				SourceState: ss,
222				UpdatedAt:   ws.UpdatedAt.Time,
223			},
224			Features: featureSummaries,
225			Tasks:    taskSummaries,
226		}, domain.SourceError{}
227	}
228	
229	// SyncWorkspace calls adapter-service to re-sync a workspace then returns updated detail.
230	// On sync failure with cached data, returns cached data marked stale.
231	// On sync failure without cached data, returns a structured source error.
232	func (s *WorkspaceService) SyncWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, domain.SourceError) {
233		if _, err := s.db.GetWorkspace(ctx, workspaceID); err != nil {
234			if errors.Is(err, database.ErrNotFound) {
235				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
236			}
237			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
238		}
239	
240		if err := s.adapter.SyncWorkspace(ctx, workspaceID); err != nil {
241			// Sync failed — try to return cached data with stale marker.
242			detail, dbErr := s.GetWorkspace(ctx, workspaceID)
243			if dbErr != (domain.SourceError{}) {
244				// No cached data — return the adapter error.
245				if se, ok := err.(domain.SourceError); ok {
246					return nil, se
247				}
248				return nil, domain.NewAdapterError(domain.ErrAdapterInternal, err.Error())
249			}
250			// Return stale cached data.
251			detail.SourceState.Stale = true
252			if se, ok := err.(domain.SourceError); ok {
253				detail.SourceState.ErrorCode = string(se.Code)
254				detail.SourceState.ErrorMessage = se.Message
255			}
256			return detail, domain.SourceError{}
257		}
258	
259		return s.GetWorkspace(ctx, workspaceID)
260	}
261	
262	// GetFeature returns feature detail with documents, tasks, and activity.
263	func (s *WorkspaceService) GetFeature(ctx context.Context, workspaceID, featureID string) (*domain.FeatureDetail, domain.SourceError) {
264		// Verify workspace exists.
265		ws, err := s.db.GetWorkspace(ctx, workspaceID)
266		if err != nil {
267			if errors.Is(err, database.ErrNotFound) {
268				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
269			}
270			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
271		}
272		wsID := database.UUIDString(ws.ID)
273	
274		feat, err := s.db.GetWorkspaceFeature(ctx, wsID, featureID)
275		if err != nil {
276			if errors.Is(err, database.ErrNotFound) {
277				return nil, domain.NewDatabaseNotFound("feature", featureID)
278			}
279			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
280		}
281	
282		featureUUID := database.UUIDString(feat.FeatureID)
283	
284		docs, err := s.db.ListFeatureDocuments(ctx, wsID, featureUUID)
285		if err != nil {
286			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
287		}
288	
289		tasks, err := s.db.ListFeatureTasks(ctx, wsID, featureUUID)
290		if err != nil {
291			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
292		}
293	
294		activity, err := s.db.ListActivityEvents(ctx, wsID, featureUUID, "")
295		if err != nil {
296			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
297		}
298	
299		syncRun, err := s.db.GetLatestSyncRun(ctx, wsID)
300		var ss domain.SourceState
301		if errors.Is(err, database.ErrNotFound) || err != nil {
302			ss = domain.DeriveSourceState(nil, s.staleThreshold)
303		} else {
304			ss = toSourceState(&syncRun, s.staleThreshold)
305		}
306	
307		counts := countTasks(tasks)
308		docLinks := make([]domain.DocumentLink, 0, len(docs))
309		for _, d := range docs {
310			docLinks = append(docLinks, domain.DocumentLink{
311				DocumentType: d.DocumentType,
312				SourcePath:   d.SourcePath,
313				URL:          derefStr(d.URL),
314			})
315		}
316	
317		taskSummaries := make([]domain.TaskSummary, 0, len(tasks))
318		for _, t := range tasks {
319			taskSummaries = append(taskSummaries, toTaskSummary(t))
320		}
321	
322		activityEvents := make([]domain.ActivityEvent, 0, len(activity))
323		for _, a := range activity {
324			activityEvents = append(activityEvents, toActivityEvent(a))
325		}
326	
327		return &domain.FeatureDetail{
328			FeatureSummary: domain.FeatureSummary{
329				ID:           database.UUIDString(feat.ID),
330				FeatureID:    database.UUIDString(feat.FeatureID),
331				FeatureName:  feat.FeatureName,
332				Title:        feat.Title,
333				Status:       derefStr(feat.FeatureStatus),
334				CurrentStage: derefStr(feat.CurrentStage),
335				Stages:       rawJSONOrNil(feat.Stages),
336				UpdatedAt:    feat.UpdatedAt.Time,
337				TaskCounts:   counts,
338			},
339			WorkspaceID: workspaceID,
340			Documents:   docLinks,
341			Tasks:       taskSummaries,
342			Activity:    activityEvents,
343			SourceState: ss,
344		}, domain.SourceError{}
345	}
346	
347	// ListFeatureTasks returns task summaries for all tasks in a feature.
348	func (s *WorkspaceService) ListFeatureTasks(ctx context.Context, workspaceID, featureID string) ([]domain.TaskSummary, domain.SourceError) {
349		feat, err := s.db.GetWorkspaceFeature(ctx, workspaceID, featureID)
350		if err != nil {
351			if errors.Is(err, database.ErrNotFound) {
352				return nil, domain.NewDatabaseNotFound("feature", featureID)
353			}
354			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
355		}
356	
357		tasks, err := s.db.ListFeatureTasks(ctx, workspaceID, database.UUIDString(feat.FeatureID))
358		if err != nil {
359			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
360		}
361	
362		out := make([]domain.TaskSummary, 0, len(tasks))
363		for _, t := range tasks {
364			out = append(out, toTaskSummary(t))
365		}
366		return out, domain.SourceError{}
367	}
368	
369	// SearchTasks returns paged task summaries for a feature filtered by search/task_id/title/status/repo.
370	func (s *WorkspaceService) SearchTasks(ctx context.Context, workspaceID, featureID string, query domain.TaskSearchQuery) (*domain.PagedTasks, domain.SourceError) {
371		if query.Page == 0 {
372			query.Page = 1
373		}
374		if query.Page < 1 {
375			return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "page must be greater than or equal to 1")
376		}
377		if query.Limit < 0 {
378			return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "limit must be greater than or equal to 0")
379		}
380		if query.Sort != "" && !isValidTaskSearchSort(query.Sort) {
381			return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "sort must be one of task_id_asc, task_id_desc, title_asc, title_desc, status_asc, status_desc, repo_asc, repo_desc, updated_at_asc, updated_at_desc, time_asc, time_desc, createdAt, -createdAt")
382		}
