695	func toTaskSummary(t database.WorkspaceTask) domain.TaskSummary {
696		isBlocked := t.Status != nil && *t.Status == "blocked"
697		return domain.TaskSummary{
698			ID:            database.UUIDString(t.ID),
699			TaskID:        database.UUIDString(t.TaskID),
700			TaskName:      t.TaskName,
701			FeatureID:     database.UUIDString(t.FeatureID),
702			FeatureName:   t.FeatureName,
703			Title:         t.Title,
704			Status:        derefStr(t.Status),
