		t.Errorf("expected adapter_service_url, got %q", cfg.API.AdapterServiceURL)
	}
	if cfg.Database.URL != "postgresql://localhost/testdb" {
		t.Errorf("expected database.url, got %q", cfg.Database.URL)
	}
}

